head.script:
// DOM 조회 순서(받은 id → mf_ 접두사 → G_ 뒤 접두사 → 접두사 제거). 2026-11
scwin.__getDom = function(id) {
	var P = 'mf_', d = function(k) { return document.getElementById(k); }, dd = function(k) { return k.replace(/(mf_){2,}/g, P); };
	var r = d(id); if (r) return r;
	var s = dd(P + id); r = d(s); if (r) return r;
	var g = s.indexOf('G_');
	if (g >= 0) { s = dd(s.slice(0, g + 2) + P + s.slice(g + 2)); r = d(s); if (r) return r; s = dd(P + s); r = d(s); if (r) return r; }
	return d(s.replace(P, ''));
};
scwin.grid1_ongroupby = function(options) {
	return false;
};
scwin.checktype = function() {
	return typeof (document.getElementById('grid1_groupbyFilterBox_select') || document.getElementById('mf_grid1_groupbyFilterBox_select'));
}
scwin.checkVal1 = function() {
	return window.getComputedStyle(scwin.__getDom($p.id + 'grid1_groupbyFilterBox_select_itemTable')).getPropertyValue('overflow-x') === 'hidden';
}
scwin.checkVal2 = function() {
	return window.getComputedStyle(scwin.__getDom($p.id + 'grid1_groupbyFilterBox_select_itemTable')).getPropertyValue('overflow-y') === 'auto';
}
scwin.onpageload = function() {
	window.arr = [];
	for (window.i = 0; i < 50000; i++) {
		for (window.j = 0; j < 7; j++) {
			arr.push(Math.floor((Math.random() * (100 - 1 + 1)) + 1));
		}
	}
	dataList1.setData(arr);
	input1.setValue(" [ 0, 1, 2] ");
	input2.setValue(" [ 1, 0, 1] ");
	input3.setValue(" { inputType:'expression', expression: 'toggle()+depthStr()+\"    [ \"+count()+\" 건 ]\"', align: 'left', colSpan:9} ");
	input4.setValue("");
	input5.setValue("");
	input6.setValue(" {colSpan:7} ");
	input7.setValue(" {hidden:true} ");
	input8.setValue(' {"category1":["1","2","3"], "category2":["1","2","3"]} ');
	input9.setValue(" [ {value:'합계'}, {inputType:'expression', expression:'SUM(\"category7\")'} ] ");
};

xf:trigger.script:
